static ret_code_t block_dev_empty_ioctl ( nrf_block_dev_t const * p_blk_dev , nrf_block_dev_ioctl_req_t req , void * p_data ) { nrf_block_dev_empty_t const * p_empty_dev = CONTAINER_OF ( p_blk_dev , nrf_block_dev_empty_t , block_dev ) ; switch ( req ) { case NRF_BLOCK_DEV_IOCTL_REQ_CACHE_FLUSH : { bool * p_flushing = p_data ; if ( p_flushing ) { * p_flushing = false ; } return NRF_SUCCESS ; } case NRF_BLOCK_DEV_IOCTL_REQ_INFO_STRINGS : { nrf_block_dev_info_strings_t const * * pp_strings = p_data ; * pp_strings = & p_empty_dev -> info_strings ; return NRF_SUCCESS ; } default : break ; } return NRF_ERROR_NOT_SUPPORTED ; } 